import React, { useState, useEffect } from "react";
import api from "../api/api";

const emptyForm = {
  type: "reseller",
  name: "",
  description: "",
  category: "",
  image: "",
  // reseller
  sourcePrice: "",
  sellingPrice: "",
  supplierName: "",
  supplierSku: "",
  stock: "",
  // affiliate
  affiliateSource: "",
  affiliateLink: "",
  displayPrice: "",
  commissionNote: "",
};

export default function AdminAddProduct() {
  const [form, setForm] = useState(emptyForm);
  const [products, setProducts] = useState([]);
  const [message, setMessage] = useState("");

  const fetchProducts = async () => {
    const res = await api.get("/products?admin=true");
    setProducts(res.data);
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const margin =
    form.type === "reseller" && form.sellingPrice && form.sourcePrice
      ? Number(form.sellingPrice) - Number(form.sourcePrice)
      : null;

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    try {
      const payload = { ...form };
      if (form.type === "reseller") {
        payload.sourcePrice = Number(form.sourcePrice);
        payload.sellingPrice = Number(form.sellingPrice);
        payload.stock = Number(form.stock) || 0;
      } else {
        payload.displayPrice = form.displayPrice ? Number(form.displayPrice) : undefined;
      }
      await api.post("/products", payload);
      setMessage("Product published!");
      setForm(emptyForm);
      fetchProducts();
    } catch (err) {
      setMessage("Error: " + (err.response?.data?.error || err.message));
    }
  };

  const handleDelete = async (id) => {
    await api.delete(`/products/${id}`);
    fetchProducts();
  };

  return (
    <div className="page container form-wide">
      <h2>Admin → Add Product</h2>

      <form onSubmit={handleSubmit}>
        <label>Product Type</label>
        <select name="type" value={form.type} onChange={handleChange}>
          <option value="reseller">Reseller (aap khud fulfill karoge)</option>
          <option value="affiliate">Affiliate (Flipkart/Amazon link se commission)</option>
        </select>

        <label>Product Name</label>
        <input className="form-input" name="name" value={form.name} onChange={handleChange} required />

        <label>Description</label>
        <textarea name="description" value={form.description} onChange={handleChange} />

        <div className="row-2">
          <div>
            <label>Category</label>
            <input className="form-input" name="category" value={form.category} onChange={handleChange} />
          </div>
          <div>
            <label>Image URL</label>
            <input className="form-input" name="image" value={form.image} onChange={handleChange} />
          </div>
        </div>

        {form.type === "reseller" ? (
          <>
            <div className="row-2">
              <div>
                <label>Source Price (₹) — supplier se aapki cost</label>
                <input className="form-input" type="number" name="sourcePrice" value={form.sourcePrice} onChange={handleChange} required />
              </div>
              <div>
                <label>Selling Price (₹) — customer ko dikhega</label>
                <input className="form-input" type="number" name="sellingPrice" value={form.sellingPrice} onChange={handleChange} required />
              </div>
            </div>
            {margin !== null && (
              <p className="success-text">Margin: ₹{margin} (automatic)</p>
            )}
            <div className="row-2">
              <div>
                <label>Supplier / Source Name</label>
                <input className="form-input" name="supplierName" value={form.supplierName} onChange={handleChange} />
              </div>
              <div>
                <label>Supplier SKU / Reference</label>
                <input className="form-input" name="supplierSku" value={form.supplierSku} onChange={handleChange} />
              </div>
            </div>
            <label>Stock Quantity</label>
            <input className="form-input" type="number" name="stock" value={form.stock} onChange={handleChange} />
          </>
        ) : (
          <>
            <div className="row-2">
              <div>
                <label>Affiliate Source (e.g. Flipkart, Amazon)</label>
                <input className="form-input" name="affiliateSource" value={form.affiliateSource} onChange={handleChange} required />
              </div>
              <div>
                <label>Display Price (₹, reference only)</label>
                <input className="form-input" type="number" name="displayPrice" value={form.displayPrice} onChange={handleChange} />
              </div>
            </div>
            <label>Official Affiliate Link</label>
            <input
              className="form-input"
              name="affiliateLink"
              placeholder="https://fkrt.it/... (Flipkart Affiliate dashboard se generate karo)"
              value={form.affiliateLink}
              onChange={handleChange}
              required
            />
            <label>Commission Note (optional, sirf reference)</label>
            <input className="form-input" name="commissionNote" placeholder="e.g. ~5% electronics par" value={form.commissionNote} onChange={handleChange} />
          </>
        )}

        {message && <p className={message.startsWith("Error") ? "error-text" : "success-text"}>{message}</p>}
        <button className="btn btn-accent" type="submit">Publish Product</button>
      </form>

      <h3 className="section-title">Existing Products</h3>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Type</th>
            <th>Price / Margin</th>
            <th>Stock / Clicks</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => (
            <tr key={p._id}>
              <td>{p.name}</td>
              <td>{p.type}</td>
              <td>
                {p.type === "reseller"
                  ? `₹${p.sellingPrice} (margin ₹${p.margin})`
                  : `₹${p.displayPrice ?? "-"} via ${p.affiliateSource}`}
              </td>
              <td>{p.type === "reseller" ? p.stock : `${p.clicks} clicks`}</td>
              <td>
                <button className="btn btn-outline btn-sm" onClick={() => handleDelete(p._id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
